</script>
<script>
/* ===== Núcleo: geometria, layout e SVG (sem DOM) ===== */
const A4 = { w: 210, h: 297 };

const SIZES = {
  big: {
    w: 55.8, h: 73.3,
    slit: [[21.06,33.87],[21.06,27.90],[33.79,27.90],[33.79,33.79],[38.60,33.79],[38.60,27.90]],
    lastBaseline: 57.26
  },
  small: {
    w: 56.4, h: 66.4,
    slit: [[23.11,19.95],[23.11,25.89],[26.21,25.89],[26.21,20.09],[34.70,20.09],[34.70,25.89],[38.60,25.89],[38.60,19.95]],  // original (26.95-32.89) movido 7 mm para CIMA (confirmado por Tiago)
    lastBaseline: 51.61
  },
  gigantic: {
    w: 65.75, h: 95.62,
    // Centerline extracted from button_gigantic_cutline.png's pink guide.
    slit: [[19.12,32.14],[19.12,38.34],[25.85,38.34],[25.85,32.14],[39.65,32.14],[39.65,38.34],[46.33,38.34],[46.33,32.14]],
    lastBaseline: 76.00
  },
  // ÍMANES_V1: não são crachás — não levam fendas nem linhas de corte.
  // Medidas tal como estão no nome dos ficheiros de origem.
  iman_corte: {
    w: 67.9, h: 104.8,
    slit: [],
    lastBaseline: 0,
    noCut: true
  },
  iman_grosso: {
    w: 53.4, h: 71.2,
    slit: [],
    lastBaseline: 0,
    noCut: true
  }
};
const LINE_SPACING = 3.175;   // 9 pt em mm
const FONT_MM = 2.434;        // 6.9 pt em mm
const TEXT_MAX_W = 38.5;      // largura útil para texto (mm)

/* ÍMANES — Escola de Pioneiros
   Tipo de letra, corpo e entrelinha vêm do original feito no Canva: Garamond
   10,2 pt, espaçamento de letra 0, entrelinha 1,4. O `capTop` é a altura (mm)
   do topo das maiúsculas da primeira linha, medida no exemplo fornecido; o
   texto é assente por aí para não depender das métricas do tipo de letra.
   Linha 1 = nome, linha 2 = congregação. */
const GARAMOND = '"Garamond","EB Garamond","Adobe Garamond Pro","Cormorant Garamond",Georgia,"Times New Roman",serif';

/* NUMBER_LINE_V1 — "TURMA 1016 - ANO 2026" vem gravada no fundo. Para a turma e
   o ano ficarem editáveis, tapa-se a linha inteira com a cor do papel e
   reescreve-se por cima, no mesmo sítio.

   Reescreve-se a linha toda (e não só os dígitos) porque há turmas com 3
   algarismos (991) e outras com 4 (1016): mexer só nos últimos dígitos deixaria
   a linha desalinhada. Ao redesenhar tudo, mantém-se sempre centrada no mesmo
   ponto do original.

   Medidas tiradas do próprio fundo, ao milímetro:
     - `clear` começa depois do floreado do "Pioneiros", que desce até à linha e
       não pode ser apagado;
     - `capTop`/`capTarget` são o topo e a altura das maiúsculas originais;
     - `centre`/`width` são o centro e a largura da linha original — a largura
       serve para calibrar o espaçamento entre letras e reproduzir o original. */
const NUMBER_LINE_CORTE = {
  sizePt: 8, capTarget: 1.76, capTop: 14.43, centre: 36.06, width: 30.03,
  clear: { x1: 20.30, y1: 14.25, x2: 51.90, y2: 16.40 },
  sample: { x: 30, y: 16.90 }
};
const NUMBER_LINE_GROSSO = {
  sizePt: 8, capTarget: 1.94, capTop: 16.68, centre: 29.65, width: 33.25,
  clear: { x1: 12.00, y1: 16.50, x2: 47.00, y2: 18.85 },
  sample: { x: 25, y: 19.30 }
};
const NUMBER_LINE_DEFAULTS = { turma: '1016', ano: '2026' };

const TEMPLATES = [
  { id:'big_blue',      label:'Grande · Azul',                size:'big',   img:'big_blue',    text:true  },
  { id:'big_green',     label:'Grande · Verde',               size:'big',   img:'big_green',   text:true  },
  { id:'small_blue',    label:'Pequeno · Azul',               size:'small', img:'small_blue',  text:true  },
  { id:'small_green',   label:'Pequeno · Verde',              size:'small', img:'small_green', text:true  },
  { id:'gigantic_blue', label:'Gigante · Azul',                size:'gigantic', img:'gigantic_blue', text:true  },
  { id:'obrigada_blue', label:'Obrigada · Azul (texto fixo)', size:'big',   img:'obrigado',    text:false },
  { id:'obrigada_green',label:'Obrigada · Verde (texto fixo)',size:'big',   img:'sticker',     text:false },
  {
    id:'iman_corte_pioneiros',
    label:'Íman corte personalizado · Escola de Pioneiros',
    size:'iman_corte', img:'iman_corte_pioneiros', text:true,
    textStyle:{
      family: GARAMOND, weight:'bold', sizePt:10.2, lineHeight:1.4,
      align:'left', x:2.11, capTop:82.89, maxW:45, box:null
    },
    numberLine: NUMBER_LINE_CORTE
  },
  {
    id:'iman_grosso_pioneiros',
    label:'Íman grosso · Escola de Pioneiros',
    size:'iman_grosso', img:'iman_grosso_pioneiros', text:true,
    textStyle:{
      family: GARAMOND, weight:'normal', sizePt:10.2, lineHeight:1.4,
      align:'center', capTop:42.36, maxW:46,
      // Caixa branca translúcida por trás do texto, com 0,5 mm de margem à volta.
      box:{ fill:'rgba(253,253,253,0.63)', pad:0.5, radius:1.75 }
    },
    numberLine: NUMBER_LINE_GROSSO
  }
];

/* Crachá PR: medidas e fendas do crachá grande, arte do íman de corte
   personalizado a preencher a largura toda (ver `artFill` em composeCard).
   O bloco do título desce 5 mm para não ficar colado ao topo.

   A arte tem conteúdo em 0,97–16,28 mm (título) e 55,79–104,27 mm (ilustração
   e citação), com 39,5 mm de papel entre os dois: o corte das duas metades é
   feito lá pelo meio. A geometria do texto acompanha a metade onde vive — a
   linha da turma pelo topo, o nome e a congregação pelo fundo. */
const CRACHA_PR_DESCE = 5;
const CRACHA_PR_CORTE = 25;
(function () {
  const base = TEMPLATES.find(t => t.id === 'iman_corte_pioneiros');
  const art = SIZES[base.size], dst = SIZES.big;
  const k = dst.w / art.w;
  const noTopo = y => y * k + CRACHA_PR_DESCE;
  const noFundo = y => dst.h - (art.h - y) * k;
  const ts = base.textStyle, nl = base.numberLine;

  TEMPLATES.push({
    id: 'cracha_pr',
    label: 'Crachá PR · Escola de Pioneiros',
    size: 'big',
    artSize: base.size,
    artFill: { topShift: CRACHA_PR_DESCE, splitCard: CRACHA_PR_CORTE },
    img: base.img,
    text: true,
    // O formato muda, o corpo do texto não: nome e congregação saem no mesmo
    // tamanho que nos ímanes, e o limite antes de encolher é o mesmo em mm.
    textStyle: Object.assign({}, ts, { x: ts.x * k, capTop: noFundo(ts.capTop) }),
    numberLine: {
      sizePt: nl.sizePt,
      capTarget: nl.capTarget * k,
      capTop: noTopo(nl.capTop),
      centre: nl.centre * k,
      width: nl.width * k,
      clear: { x1: nl.clear.x1 * k, y1: noTopo(nl.clear.y1),
               x2: nl.clear.x2 * k, y2: noTopo(nl.clear.y2) },
      sample: { x: nl.sample.x * k, y: noTopo(nl.sample.y) }
    }
  });
}());

const SIZE_LABELS = {
  big: { one: 'grande', many: 'grandes' },
  small: { one: 'pequeno', many: 'pequenos' },
  gigantic: { one: 'gigante', many: 'gigantes' },
  iman_corte: { one: 'íman corte personalizado', many: 'ímanes corte personalizado' },
  iman_grosso: { one: 'íman grosso', many: 'ímanes grossos' }
};

function sizeLabel(sizeKey, plural) {
  const label = SIZE_LABELS[sizeKey];
  return label ? (plural ? label.many : label.one) : sizeKey;
}

function cardDims(sizeKey, card) {
  const s = SIZES[sizeKey];
  return (card && card.rot === 90) ? { w: s.h, h: s.w } : { w: s.w, h: s.h };
}

function cardPoint(sizeKey, card, p) {
  const s = SIZES[sizeKey];
  if (card && card.rot === 90) return [card.x + s.h - p[1], card.y + p[0]];
  return [card.x + p[0], card.y + p[1]];
}

function cardSlitPoints(sizeKey, card) {
  return SIZES[sizeKey].slit.map(p => cardPoint(sizeKey, card, p));
}

/* ---------- seleção de posições na grelha da folha ---------- */
let posSel = null;                       // Set de "c,r" ativas
let posDims = { cols: 0, rows: 0, cellW: 24, cellH: 30 };

function posKey(c, r) { return c + ',' + r; }
function allCells(cols, rows) {
  const out = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) out.push({ c, r });
  return out;
}
/* Garante que o painel corresponde à grelha atual; se as dimensões mudarem, volta a "todas" */
function ensurePosGrid(cols, rows, box) {
  if (posDims.cols !== cols || posDims.rows !== rows || !posSel) {
    posDims.cols = cols; posDims.rows = rows;
    posSel = new Set(allCells(cols, rows).map(({c,r}) => posKey(c, r)));
  }
  if (box) {
    posDims.cellW = 26;
    posDims.cellH = Math.max(16, Math.min(44, Math.round(26 * box.h / box.w)));
  }
  renderPosGrid();
}
function selectedCells(cols, rows) {
  if (!posSel || posDims.cols !== cols || posDims.rows !== rows) return allCells(cols, rows);
  return allCells(cols, rows).filter(({c,r}) => posSel.has(posKey(c, r)));
}
function togglePos(c, r) {
  const k = posKey(c, r);
  if (posSel.has(k)) { if (posSel.size > 1) posSel.delete(k); }
  else posSel.add(k);
  renderPosGrid();
  refresh();
}
function posAll() { posSel = null; ensurePosGrid(posDims.cols, posDims.rows); refresh(); }
function renderPosGrid() {
  const el = document.getElementById('posGrid');
  if (!el || !posDims.cols) return;
  el.style.gridTemplateColumns = `repeat(${posDims.cols}, ${posDims.cellW}px)`;
  let ord = 0, h = '';
  for (let r = 0; r < posDims.rows; r++)
    for (let c = 0; c < posDims.cols; c++) {
      const on = posSel.has(posKey(c, r));
      const num = on ? ++ord : '';
      h += `<div onclick="togglePos(${c},${r})" title="coluna ${c+1}, linha ${r+1}" style="width:${posDims.cellW}px;height:${posDims.cellH}px;line-height:${posDims.cellH}px;text-align:center;font-size:11px;font-weight:700;border:1px solid #bbb;border-radius:3px;cursor:pointer;user-select:none;${on ? 'background:var(--accent);color:#fff' : 'background:#f3f3f3;color:#bbb'}">${num}</div>`;
    }
  el.innerHTML = h;
}

/* Divide um lote em folhas A4 */
function layoutSheets(sizeKey, count, margin, landscape) {
  const s = SIZES[sizeKey];
  const box = landscape ? { w: s.h, h: s.w } : { w: s.w, h: s.h };
  const cols = Math.floor((A4.w - 2*margin) / box.w);
  const rows = Math.floor((A4.h - 2*margin) / box.h);
  if (cols * rows < 1) return [];
  // Grelha fixa (a mesma de uma folha cheia); só as posições selecionadas são usadas,
  // pela ordem esquerda→direita, cima→baixo
  const cells = selectedCells(cols, rows);
  const per = cells.length;
  const partial = per < cols * rows;
  const x0 = (A4.w - cols * box.w) / 2;
  const y0 = (A4.h - rows * box.h) / 2;
  const sheets = [];
  let remaining = count;
  while (remaining > 0) {
    const n = Math.min(per, remaining);
    const used = cells.slice(0, n);
    const cards = used.map(({c, r}) =>
      ({ x: x0 + c * box.w, y: y0 + r * box.h, rot: landscape ? 90 : 0 }));
    sheets.push({ cards, cols: Math.min(n, cols), rows: Math.ceil(n / cols), n,
                  posTag: partial ? '_p' + used.map(({c,r}) => r * cols + c + 1).join('-') : '' });
    remaining -= n;
  }
  return sheets;
}

/* Funde segmentos colineares e remove duplicados */
function mergeSegments(segs) {
  const r2 = v => Math.round(v * 100) / 100;
  const horiz = new Map(), vert = new Map();
  for (const [x1,y1,x2,y2] of segs) {
    if (Math.abs(y1-y2) < 0.001) {
      const k = r2(y1); if (!horiz.has(k)) horiz.set(k, []);
      horiz.get(k).push([Math.min(x1,x2), Math.max(x1,x2)]);
    } else {
      const k = r2(x1); if (!vert.has(k)) vert.set(k, []);
      vert.get(k).push([Math.min(y1,y2), Math.max(y1,y2)]);
    }
  }
  const out = [];
  const mergeRuns = (map, isH) => {
    for (const [k, runs] of map) {
      runs.sort((a,b) => a[0]-b[0]);
      let [a,b] = runs[0];
      for (let i = 1; i < runs.length; i++) {
        const [c,d] = runs[i];
        if (c <= b + 0.01) b = Math.max(b, d);
        else { out.push(isH ? [a,k,b,k] : [k,a,k,b]); [a,b] = [c,d]; }
      }
      out.push(isH ? [a,k,b,k] : [k,a,k,b]);
    }
  };
  mergeRuns(horiz, true); mergeRuns(vert, false);
  return out;
}

/* Geometria de corte de uma folha, com offsets aplicados:
   { segs: segmentos da grelha [[x1,y1,x2,y2]...], slits: [[ [x,y]... ] por cartão] } */
function sheetCutGeometry(sizeKey, sheet, off) {
  off = Object.assign({ gx:0, gy:0, sx:0, sy:0, grid:false, extraTop:true }, off || {});
  const raw = [];
  for (const c of sheet.cards) {
    const d = cardDims(sizeKey, c);
    raw.push([c.x, c.y, c.x + d.w, c.y]);
    raw.push([c.x, c.y + d.h, c.x + d.w, c.y + d.h]);
    raw.push([c.x, c.y, c.x, c.y + d.h]);
    raw.push([c.x + d.w, c.y, c.x + d.w, c.y + d.h]);
  }
  // linha extra exatamente 2 mm acima da linha de corte superior (só no modo manual)
  if (off.extraTop) {
    const minY = Math.min(...sheet.cards.map(c => c.y));
    const topCards = sheet.cards.filter(c => Math.abs(c.y - minY) < 0.001);
    const xL = Math.min(...topCards.map(c => c.x));
    const xR = Math.max(...topCards.map(c => c.x + cardDims(sizeKey, c).w));
    raw.push([xL, minY - 2, xR, minY - 2]);
  }
  const segs = off.grid ? mergeSegments(raw).map(([x1,y1,x2,y2]) =>
    [x1 + off.gx, y1 + off.gy, x2 + off.gx, y2 + off.gy]) : [];   // sem 'grid': só as fendas são cortadas
  const slits = sheet.cards.map(c =>
    cardSlitPoints(sizeKey, c).map(p => [p[0] + off.gx + off.sx, p[1] + off.gy + off.sy]));  // fendas seguem o corte global + ajuste próprio
  return { segs, slits };
}

/* SVG de corte (preview=true → SVG colorido com camada fantasma da impressão) */
function sheetCutSVG(sizeKey, sheet, off, preview) {
  const s = SIZES[sizeKey];
  const f2 = v => v.toFixed(2);
  const g = sheetCutGeometry(sizeKey, sheet, off);
  const cuts = g.segs.map(([x1,y1,x2,y2]) =>
    `<path d="M ${f2(x1)} ${f2(y1)} L ${f2(x2)} ${f2(y2)}"/>`).join('\n    ');
  const slits = g.slits.map(pts =>
    `<path d="${pts.map((p,i) => `${i ? 'L' : 'M'} ${f2(p[0])} ${f2(p[1])}`).join(' ')}"/>`).join('\n    ');

  if (preview) {
    const ghost = sheet.cards.map(c => {
      const d = cardDims(sizeKey, c);
      const sd = cardSlitPoints(sizeKey, c).map((p,i) => `${i ? 'L' : 'M'} ${f2(p[0])} ${f2(p[1])}`).join(' ');
      return `<rect x="${f2(c.x)}" y="${f2(c.y)}" width="${f2(d.w)}" height="${f2(d.h)}"/><path d="${sd}"/>`;
    }).join('\n    ');
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 210 297">
  <rect x="0" y="0" width="210" height="297" fill="#fff" stroke="#ddd" stroke-width="0.4"/>
  <g fill="none" stroke="#c9bfae" stroke-width="0.5" stroke-dasharray="1.5,1.5">
    ${ghost}
  </g>
  <g fill="none" stroke="#3b6ea5" stroke-width="0.7">
    ${cuts}
  </g>
  <g fill="none" stroke="#e84393" stroke-width="0.7">
    ${slits}
  </g>
</svg>`;
  }
  return `<${"?"}xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="210mm" height="297mm" viewBox="0 0 210 297">
  <g id="moldura-a4-apagar-antes-de-cortar" fill="none" stroke="#FF0000" stroke-width="0.2">
    <rect x="0" y="0" width="210" height="297"/>
  </g>
  <g id="cortes" fill="none" stroke="#000000" stroke-width="0.2">
    ${cuts}
    ${slits}
  </g>
</svg>`;
}


/* ===== Print Then Cut ===== */
const PTC = { w: 171.4, h: 235.0 };   // área máxima PTC do Design Space (6.75 × 9.25 pol)

/* Folhas PTC: bloco de cartões com origem em (0,0), limitado à área PTC */
function ptcLayoutSheets(sizeKey, count, landscape) {
  const s = SIZES[sizeKey];
  const box = landscape ? { w: s.h, h: s.w } : { w: s.w, h: s.h };
  const cols = Math.floor(PTC.w / box.w);
  const rows = Math.floor(PTC.h / box.h);
  const per = cols * rows;
  if (per < 1) return [];
  const sheets = [];
  let remaining = count;
  while (remaining > 0) {
    const n = Math.min(per, remaining);
    const usedCols = Math.min(n, cols);
    const usedRows = Math.ceil(n / cols);
    const cards = [];
    for (let i = 0; i < n; i++) {
      const col = i % cols, r = Math.floor(i / cols);
      cards.push({ x: col * box.w, y: r * box.h, rot: landscape ? 90 : 0 });
    }
    sheets.push({ cards, cols: usedCols, rows: usedRows, n,
                  blockW: usedCols * box.w, blockH: usedRows * box.h });
    remaining -= n;
  }
  return sheets;
}

/* SVG PTC: imagem embebida (camada de impressão) + linhas de corte por cima */
function ptcSVG(sizeKey, sheet, off, imgHref, preview) {
  off = Object.assign({}, off || {});
  off.extraTop = false;                       // sem linha extra no PTC (o sensor alinha)
  const f2 = v => v.toFixed(2);
  const s = SIZES[sizeKey];
  const g = sheetCutGeometry(sizeKey, sheet, off);
  const W = sheet.blockW, H = sheet.blockH;
  const cuts = g.segs.map(([x1,y1,x2,y2]) =>
    `<path d="M ${f2(x1)} ${f2(y1)} L ${f2(x2)} ${f2(y2)}"/>`).join('\n    ');
  const slits = g.slits.map(pts =>
    `<path d="${pts.map((p,i) => `${i ? 'L' : 'M'} ${f2(p[0])} ${f2(p[1])}`).join(' ')}"/>`).join('\n    ');
  if (preview) {
    const ghost = sheet.cards.map(c => {
      const d = cardDims(sizeKey, c);
      const sd = cardSlitPoints(sizeKey, c).map((p,i) => `${i ? 'L' : 'M'} ${f2(p[0])} ${f2(p[1])}`).join(' ');
      return `<rect x="${f2(c.x)}" y="${f2(c.y)}" width="${f2(d.w)}" height="${f2(d.h)}"/><path d="${sd}"/>`;
    }).join('\n    ');
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-2 -2 ${f2(W+4)} ${f2(H+4)}">
  <rect x="0" y="0" width="${f2(W)}" height="${f2(H)}" fill="#fff" stroke="#888" stroke-width="0.5"/>
  <g fill="none" stroke="#c9bfae" stroke-width="0.5" stroke-dasharray="1.5,1.5">
    ${ghost}
  </g>
  <g fill="none" stroke="#3b6ea5" stroke-width="0.7">
    ${cuts}
  </g>
  <g fill="none" stroke="#e84393" stroke-width="0.7">
    ${slits}
  </g>
</svg>`;
  }
  return `<${"?"}xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${f2(W)}mm" height="${f2(H)}mm" viewBox="0 0 ${f2(W)} ${f2(H)}">
  <g id="imprimir">
    <image x="0" y="0" width="${f2(W)}" height="${f2(H)}" preserveAspectRatio="none" href="${imgHref}" xlink:href="${imgHref}"/>
  </g>
  <g id="cortes" fill="none" stroke="#000000" stroke-width="0.2">
    ${cuts}
    ${slits}
  </g>
</svg>`;
}

if (typeof module !== 'undefined') module.exports = { A4, SIZES, PTC, LINE_SPACING, FONT_MM, TEXT_MAX_W, TEMPLATES, SIZE_LABELS, sizeLabel, cardDims, cardPoint, cardSlitPoints, layoutSheets, ptcLayoutSheets, mergeSegments, sheetCutGeometry, sheetCutSVG, ptcSVG };

</script>
<script>
const IMAGES = {
  // Fundos dos ímanes: ficheiros próprios em tools/cartoes/ (loadImg aceita
  // caminhos .png além de base64). Mesma origem, por isso a canvas não fica
  // "tainted" e o toDataURL para o PDF continua a funcionar.
  iman_corte_pioneiros: "cartoes/iman-corte-personalizado-pioneiros.webp",
  iman_grosso_pioneiros: "cartoes/iman-grosso-pioneiros.webp",
  gigantic_blue: "",
  big_blue: "",
  big_green: "",
  small_blue: "",
  small_green: "",
  obrigado: "",
  sticker: ""
};
const FONT_LATIN = "";
const FONT_LATIN_EXT = "";

/* ---------- fontes ---------- */
let fontsReady = (async () => {
  for (const b64 of [FONT_LATIN, FONT_LATIN_EXT]) {
    const ff = new FontFace('Nunito', `url(data:font/woff2;base64,${b64})`, { style: 'italic', weight: '400' });
    await ff.load(); document.fonts.add(ff);
  }
})();

/* ---------- imagens ---------- */
const imgCache = {};
function loadImg(key) {
  if (imgCache[key]) return imgCache[key];
  imgCache[key] = new Promise(res => {
    const im = new Image();
    im.onload = () => res(im);
    const src = IMAGES[key];
    im.src = /^(data:|https?:|file:)/i.test(src) || /\.(?:png|webp)([?#].*)?$/i.test(src)
      ? src
      : 'data:image/png;base64,' + src;
  });
  return imgCache[key];
}

/* ---------- número com vírgula ou ponto ---------- */
function num(v) { return parseFloat(String(v).replace(',', '.')) || 0; }

/* ---------- composição do cartão ---------- */
async function composeCard(tpl, lines, canvas, textY, nums) {
  await fontsReady;
  const s = SIZES[tpl.size];
  const img = await loadImg(tpl.img);
  const W = img.naturalWidth || img.width || 639; // resolucao nativa (~290 dpi)
  const H = Math.round(W * s.h / s.w);
  const cv = canvas || document.createElement('canvas');
  cv.width = W; cv.height = H;
  const ctx = cv.getContext('2d');
  if (tpl.artFill) {
    /* A arte é mais estreita e mais alta do que este cartão. Para a pôr o
       maior possível sem cortar nada, enche-se a largura toda e o que sobra em
       altura sai da faixa em branco do meio: o bloco do título fica encostado
       ao topo e o bloco da ilustração encostado ao fundo. As duas metades
       encontram-se em `splitCard`, que cai dentro dessa faixa vazia. */
    const art = SIZES[tpl.artSize];
    const px = W / s.w;
    const k = s.w / art.w;
    const srcPx = (img.naturalWidth || img.width) / art.w;
    const desce = tpl.artFill.topShift || 0;
    const corte = tpl.artFill.splitCard;

    const fundoDesde = art.h - (s.h - corte) / k;
    ctx.drawImage(img, 0, fundoDesde * srcPx, img.naturalWidth, (art.h - fundoDesde) * srcPx,
      0, corte * px, W, (s.h - corte) * px);

    let papel = '#ffffff';
    try {
      const p = ctx.getImageData(Math.round(3 * px), Math.round((corte + 1) * px), 1, 1).data;
      papel = 'rgb(' + p[0] + ',' + p[1] + ',' + p[2] + ')';
    } catch (e) { /* canvas sem acesso aos pixéis: fica o branco */ }
    ctx.fillStyle = papel;
    ctx.fillRect(0, 0, W, Math.round(corte * px));

    const topoAte = (corte - desce) / k;
    ctx.drawImage(img, 0, 0, img.naturalWidth, topoAte * srcPx,
      0, desce * px, W, topoAte * k * px);
  } else {
    ctx.drawImage(img, 0, 0, W, H);
  }
  if (tpl.numberLine) drawNumberLine(ctx, tpl, W, nums);
  if (tpl.text && tpl.textStyle) {
    drawStyledText(ctx, tpl, lines, W, textY);
  } else if (tpl.text) {
    const px = W / s.w;
    const fontPx = FONT_MM * px;
    const ls = lines.filter(t => t.trim() !== '');
    ctx.fillStyle = '#000';
    ctx.textAlign = 'center';
    const lastB = (s.lastBaseline + (textY || 0)) * px, spacing = LINE_SPACING * px;
    ls.forEach((t, i) => {
      ctx.font = `italic ${fontPx}px Nunito`;
      ctx.fillText(t, W / 2, lastB - (ls.length - 1 - i) * spacing);
    });
  }
  drawCutOutline(ctx, tpl, W, H);
  return cv;
}

/* CUT_OUTLINE_V1 — linha à volta do cartão, para cortar à mão. Fica desenhada
   na própria imagem do cartão, e não no PDF por cima, para a espessura ser
   exactamente a pedida e o "com/sem suavização" ter efeito real:
     - com suavização: traço da largura exacta em mm, com as pontas esbatidas;
     - sem suavização: barras cheias encostadas à grelha de pixéis, sem meios-tons. */
function drawCutOutline(ctx, tpl, W, H) {
  const c = getCutOutline();
  if (!c.on) return;
  const s = SIZES[tpl.size];
  const larguraPx = Math.max(0.01, c.mm) * (W / s.w);

  if (c.alias) {
    ctx.strokeStyle = c.cor;
    ctx.lineWidth = larguraPx;
    ctx.strokeRect(larguraPx / 2, larguraPx / 2, W - larguraPx, H - larguraPx);
  } else {
    const t = Math.max(1, Math.round(larguraPx));
    ctx.fillStyle = c.cor;
    ctx.fillRect(0, 0, W, t);
    ctx.fillRect(0, H - t, W, t);
    ctx.fillRect(0, 0, t, H);
    ctx.fillRect(W - t, 0, t, H);
  }
}

function hexParaRgb(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ''));
  if (!m) return [220, 220, 220];
  const n = parseInt(m[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function getCutOutline() {
  const el = id => document.getElementById(id);
  if (!el('cutline')) return { on: false };
  return {
    on: el('cutline').checked,
    mm: num(el('cutlineW').value) || 0.1,
    cor: el('cutlineC').value || '#dcdcdc',
    alias: el('cutlineA').checked
  };
}

/* Texto dos ímanes: assente pelo topo das maiúsculas da primeira linha, para o
   resultado não mudar se o tipo de letra instalado tiver métricas diferentes.
   Linhas largas de mais encolhem até caberem, em vez de invadirem a ilustração. */
function drawStyledText(ctx, tpl, lines, W, textY) {
  const st = tpl.textStyle;
  const s = SIZES[tpl.size];
  const px = W / s.w;
  const ls = lines.filter(t => t.trim() !== '');
  if (!ls.length) return;

  const sizeMm = st.sizePt * 25.4 / 72;
  const lineMm = sizeMm * st.lineHeight;
  const fontFor = mm => `${st.weight === 'bold' ? 'bold ' : ''}${mm * px}px ${st.family}`;

  ctx.font = fontFor(sizeMm);
  const capMm = ctx.measureText('H').actualBoundingBoxAscent / px;

  const drawn = ls.map(t => {
    let mm = sizeMm;
    ctx.font = fontFor(mm);
    const w = ctx.measureText(t).width / px;
    if (st.maxW && w > st.maxW) mm = Math.max(sizeMm * 0.7, mm * st.maxW / w);
    ctx.font = fontFor(mm);
    const m = ctx.measureText(t);
    return { t, mm, w: m.width / px, desc: m.actualBoundingBoxDescent / px };
  });

  const capTop = st.capTop + (textY || 0);
  const centreX = st.align === 'center' ? s.w / 2 : null;
  const leftOf = d => st.align === 'center' ? centreX - d.w / 2 : st.x;

  if (st.box) {
    const left = Math.min(...drawn.map(leftOf)) - st.box.pad;
    const right = Math.max(...drawn.map(d => leftOf(d) + d.w)) + st.box.pad;
    const last = drawn[drawn.length - 1];
    const bottom = capTop + (drawn.length - 1) * lineMm + capMm + last.desc + st.box.pad;
    const top = capTop - st.box.pad;
    ctx.fillStyle = st.box.fill;
    ctx.beginPath();
    roundRectPath(ctx, left * px, top * px, (right - left) * px, (bottom - top) * px, st.box.radius * px);
    ctx.fill();
  }

  ctx.fillStyle = '#000';
  ctx.textAlign = st.align === 'center' ? 'center' : 'left';
  ctx.textBaseline = 'alphabetic';
  drawn.forEach((d, i) => {
    ctx.font = fontFor(d.mm);
    const baseline = (capTop + capMm + i * lineMm) * px;
    ctx.fillText(d.t, (st.align === 'center' ? centreX : st.x) * px, baseline);
  });
}

/* Tapa a linha "TURMA … - ANO …" gravada no fundo e reescreve-a com os valores
   pedidos. Só desenha se pelo menos um dos campos estiver preenchido; em branco
   fica o fundo original intacto. */
function drawNumberLine(ctx, tpl, W, nums) {
  const nl = tpl.numberLine;
  const s = SIZES[tpl.size];
  const px = W / s.w;
  const turma = String((nums && nums.turma) || '').trim();
  const ano = String((nums && nums.ano) || '').trim();
  if (!turma && !ano) return;

  const texto = 'TURMA ' + (turma || NUMBER_LINE_DEFAULTS.turma)
    + ' - ANO ' + (ano || NUMBER_LINE_DEFAULTS.ano);

  // Cor do papel, lida do próprio fundo para o remendo não se notar.
  let papel = '#ffffff';
  try {
    const p = ctx.getImageData(Math.round(nl.sample.x * px), Math.round(nl.sample.y * px), 1, 1).data;
    papel = 'rgb(' + p[0] + ',' + p[1] + ',' + p[2] + ')';
  } catch (e) { /* canvas sem acesso aos pixéis: fica o branco */ }

  ctx.fillStyle = papel;
  ctx.fillRect(nl.clear.x1 * px, nl.clear.y1 * px,
    (nl.clear.x2 - nl.clear.x1) * px, (nl.clear.y2 - nl.clear.y1) * px);

  // Corpo ajustado para as maiúsculas ficarem com a altura do original.
  const nominal = nl.sizePt * 25.4 / 72;
  const fontAt = mm => mm * px + 'px ' + GARAMOND;
  ctx.font = fontAt(nominal);
  const capNominal = ctx.measureText('H').actualBoundingBoxAscent / px;
  const sizeMm = capNominal > 0 ? nominal * (nl.capTarget / capNominal) : nominal;
  ctx.font = fontAt(sizeMm);
  const capMm = ctx.measureText('H').actualBoundingBoxAscent / px;

  // Espaçamento entre letras calibrado pela largura da linha original, medido
  // com os valores de origem para o resultado assentar onde assentava.
  const padrao = 'TURMA ' + NUMBER_LINE_DEFAULTS.turma + ' - ANO ' + NUMBER_LINE_DEFAULTS.ano;
  const suporta = 'letterSpacing' in ctx;
  if (suporta) ctx.letterSpacing = '0px';
  const larguraBase = ctx.measureText(padrao).width / px;
  if (suporta && padrao.length > 1) {
    ctx.letterSpacing = ((nl.width - larguraBase) * px / (padrao.length - 1)) + 'px';
  }

  ctx.fillStyle = '#000';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';
  // A canvas conta o espaçamento também depois da última letra; meio desse
  // excesso corrige o centro para o texto assentar onde assentava o original.
  const extra = suporta ? parseFloat(ctx.letterSpacing) / px : 0;
  ctx.fillText(texto, (nl.centre + extra / 2) * px, (nl.capTop + capMm) * px);
  if (suporta) ctx.letterSpacing = '0px';
}

function roundRectPath(ctx, x, y, w, h, r) {
  if (ctx.roundRect) { ctx.roundRect(x, y, w, h, r); return; }
  const rad = Math.min(r, w / 2, h / 2);
  ctx.moveTo(x + rad, y);
  ctx.arcTo(x + w, y, x + w, y + h, rad);
  ctx.arcTo(x + w, y + h, x, y + h, rad);
  ctx.arcTo(x, y + h, x, y, rad);
  ctx.arcTo(x, y, x + w, y, rad);
  ctx.closePath();
}

function rotateCanvas90(cv) {
  const out = document.createElement('canvas');
  out.width = cv.height;
  out.height = cv.width;
  const ctx = out.getContext('2d');
  ctx.translate(out.width, 0);
  ctx.rotate(Math.PI / 2);
  ctx.drawImage(cv, 0, 0);
  return out;
}

async function composePlacedCard(tpl, lines, textY, landscape, nums) {
  const cv = await composeCard(tpl, lines, null, textY, nums);
  return landscape ? rotateCanvas90(cv) : cv;
}

/* ---------- lotes (UI) ---------- */
let batchSeq = 0;
function addBatch(data) {
  const tb = document.querySelector('#batches tbody');
  const tr = document.createElement('tr');
  tr.dataset.id = ++batchSeq;
  const opts = TEMPLATES.map(t => `<option value="${t.id}">${t.label}</option>`).join('');
  tr.innerHTML = `
    <td><select class="tpl" onchange="refresh()">${opts}</select></td>
    <td><input type="text" class="l1" list="dlL1" placeholder="ex.: Samuel, Zeza e Sofia" oninput="onL1Input(this)"></td>
    <td><input type="text" class="l2" list="dlL2" placeholder="ex.: email / telefone" oninput="refresh()"></td>
    <td><input type="text" class="l3" list="dlL3" placeholder="ex.: congregação" oninput="refresh()"></td>
    <td><input type="text" class="turma" size="5" maxlength="5" inputmode="numeric" title="Número da turma impresso no cartão" oninput="refresh()"></td>
    <td><input type="text" class="ano" size="5" maxlength="4" inputmode="numeric" title="Ano impresso no cartão" oninput="refresh()"></td>
    <td><input type="number" class="ty" value="0" step="0.1" title="Ajuste vertical do texto (mm)" onchange="refresh()"></td>
    <td><input type="number" class="qty" value="12" min="1" max="500" onchange="refresh()"></td>
    <td><button class="del" onclick="this.closest('tr').remove(); refresh()">✕</button></td>`;
  tb.appendChild(tr);
  if (data) {
    tr.querySelector('.tpl').value = data.tpl;
    tr.querySelector('.l1').value = data.l1 || '';
    tr.querySelector('.l2').value = data.l2 || '';
    tr.querySelector('.l3').value = data.l3 || '';
    tr.querySelector('.turma').value = data.turma || '';
    tr.querySelector('.ano').value = data.ano || '';
    tr.querySelector('.ty').value = data.ty || 0;
    tr.querySelector('.qty').value = data.qty;
  }
  tr.addEventListener('focusin', () => { focused = tr; refresh(); });
  refresh();
}

function readBatches() {
  return [...document.querySelectorAll('#batches tbody tr')].map(tr => ({
    tr,
    tpl: TEMPLATES.find(t => t.id === tr.querySelector('.tpl').value),
    lines: [tr.querySelector('.l1').value, tr.querySelector('.l2').value, tr.querySelector('.l3').value],
    nums: { turma: tr.querySelector('.turma').value, ano: tr.querySelector('.ano').value },
    ty: num(tr.querySelector('.ty').value),
    qty: parseInt(tr.querySelector('.qty').value) || 0
  })).filter(b => b.qty > 0);
}

/* Turma e ano só existem nos modelos que trazem a linha gravada no fundo. Nos
   restantes os campos ficam desligados, para não parecerem uma opção. */
function syncNumberFields() {
  document.querySelectorAll('#batches tbody tr').forEach(tr => {
    const tpl = TEMPLATES.find(t => t.id === tr.querySelector('.tpl').value);
    const usa = !!(tpl && tpl.numberLine);
    ['turma', 'ano'].forEach(campo => {
      const el = tr.querySelector('.' + campo);
      el.disabled = !usa;
      el.placeholder = usa ? NUMBER_LINE_DEFAULTS[campo] : '—';
      el.style.opacity = usa ? '' : '0.35';
      if (!usa) el.value = '';
    });
  });
}

/* ---------- calibração ---------- */
function getOffsets() {
  const v = id => num(document.getElementById(id).value);
  return { gx: v('offGx'), gy: v('offGy'), sx: v('offSx'), sy: v('offSy'), grid: document.getElementById('legacy').checked, ptc: document.getElementById('ptc').checked };
}
function isLandscapeLayout() {
  return document.getElementById('landscape').checked;
}
function step(id, d) {
  const el = document.getElementById(id);
  el.value = Math.round((num(el.value) + d) * 100) / 100;
  refresh();
}

/* ---------- pré-visualização ---------- */
let focused = null, refreshTimer = null;
function refresh() {
  clearTimeout(refreshTimer);
  syncNumberFields();
  refreshTimer = setTimeout(async () => {
    const batches = readBatches();
    if (!batches.length) return;
    const off = getOffsets();
    const b = batches.find(x => x.tr === focused) || batches[0];
    const cv = document.getElementById('preview');
    const s = SIZES[b.tpl.size];
    await composeCard(b.tpl, b.lines, cv, b.ty, b.nums);
    const ctx = cv.getContext('2d'), px = cv.width / s.w;
    ctx.strokeStyle = '#e84393'; ctx.lineWidth = 2;
    ctx.beginPath();
    s.slit.forEach((p, i) => i ? ctx.lineTo((p[0]+off.gx+off.sx)*px, (p[1]+off.gy+off.sy)*px) : ctx.moveTo((p[0]+off.gx+off.sx)*px, (p[1]+off.gy+off.sy)*px));
    ctx.stroke();
    // Moldura só para dar limite ao cartão no ecrã. Com a linha de corte ligada
    // seria desenhada mesmo por cima dela e escondia-a — aí o cartão já tem
    // limite próprio e mostra-se a linha verdadeira.
    if (!getCutOutline().on) { ctx.strokeStyle = '#bbb'; ctx.strokeRect(0, 0, cv.width, cv.height); }
    const margin = num(document.getElementById('margin').value);
    const landscape = isLandscapeLayout();
    const sameSize = batches.filter(x => x.tpl.size === b.tpl.size);
    const total = sameSize.reduce((a, x) => a + x.qty, 0);
    { // atualiza o painel de posições para a grelha atual (tamanho + margem + orientação)
      const boxB = landscape ? { w: s.h, h: s.w } : { w: s.w, h: s.h };
      ensurePosGrid(Math.floor((A4.w - 2*margin) / boxB.w), Math.floor((A4.h - 2*margin) / boxB.h), boxB);
    }
    const sheets = off.ptc ? ptcLayoutSheets(b.tpl.size, total, landscape) : layoutSheets(b.tpl.size, total, margin, landscape);
    if (sheets.length) {
      document.getElementById('sheetPrev').innerHTML = off.ptc
        ? ptcSVG(b.tpl.size, sheets[0], off, null, true)
        : sheetCutSVG(b.tpl.size, sheets[0], off, true);
      const tam = sizeLabel(b.tpl.size, true);
      document.getElementById('sheetInfo').textContent =
        `${total} cartões ${tam}${landscape ? ' deitados' : ''} (${sameSize.length} lote(s)) → ${sheets.length} folha(s) (${sheets.map(x => x.n).join(' + ')})${off.ptc ? ' · Print Then Cut' : ''}`;
    }
  }, 200);
}

/* ---------- IndexedDB (guardar o handle do nomes.txt) ---------- */
function idbOpen() {
  return new Promise((res, rej) => {
    const rq = indexedDB.open('miaPaper', 1);
    rq.onupgradeneeded = () => rq.result.createObjectStore('kv');
    rq.onsuccess = () => res(rq.result);
    rq.onerror = () => rej(rq.error);
  });
}
async function idbGet(k) {
  const db = await idbOpen();
  return new Promise((res, rej) => {
    const rq = db.transaction('kv').objectStore('kv').get(k);
    rq.onsuccess = () => res(rq.result); rq.onerror = () => rej(rq.error);
  });
}
async function idbSet(k, v) {
  const db = await idbOpen();
  return new Promise((res, rej) => {
    const tx = db.transaction('kv', 'readwrite');
    tx.objectStore('kv').put(v, k);
    tx.oncomplete = () => res(); tx.onerror = () => rej(tx.error);
  });
}

/* ---------- nomes.txt (estilo INI) ---------- */
let NAMES = [];
let namesHandle = null;
function parseNames(text) {
  const entries = [];
  let cur = null;
  for (let raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith(';') || line.startsWith('#')) continue;
    const sec = line.match(/^\[(.+)\]$/);
    if (sec) { cur = { name: sec[1].trim(), linha1: '', linha2: '', linha3: '', textoy: 0 }; entries.push(cur); continue; }
    const kv = line.match(/^(linha[123]|textoy)\s*=\s*(.*)$/i);
    if (kv && cur) {
      const key = kv[1].toLowerCase();
      if (key === 'textoy') cur.textoy = num(kv[2]);
      else cur[key] = kv[2].trim();
    }
  }
  for (const e of entries) if (!e.linha1) e.linha1 = e.name;
  return entries.filter(e => e.linha1);
}
function serializeNames(entries) {
  let out = '; ===== Mia & Paper — nomes pré-carregados =====\n';
  out += '; [Nome] + linha1 / linha2 / linha3 + textoy (ajuste Y do texto em mm, opcional)\n';
  out += '; Este ficheiro é carregado automaticamente se estiver na mesma pasta.\n\n';
  for (const e of entries) {
    out += `[${e.name || e.linha1}]\n`;
    out += `linha1 = ${e.linha1}\n`;
    if (e.linha2) out += `linha2 = ${e.linha2}\n`;
    if (e.linha3) out += `linha3 = ${e.linha3}\n`;
    if (e.textoy) out += `textoy = ${e.textoy}\n`;
    out += '\n';
  }
  return out;
}
function applyNames(entries, sourceLabel) {
  NAMES = entries;
  const fill = (id, vals) => {
    document.getElementById(id).innerHTML =
      [...new Set(vals.filter(v => v))].map(v => `<option value="${v.replace(/"/g,'&quot;')}">`).join('');
  };
  fill('dlL1', entries.map(e => e.linha1));
  fill('dlL2', entries.map(e => e.linha2));
  fill('dlL3', entries.map(e => e.linha3));
  document.getElementById('namesInfo').textContent =
    entries.length ? `${entries.length} nome(s) · ${sourceLabel || ''}` : '';
  try { localStorage.setItem('miaNames', JSON.stringify(entries)); } catch (e) {}
}
function onL1Input(inp) {
  const e = NAMES.find(x => x.linha1 === inp.value || x.name === inp.value);
  if (e) {
    const tr = inp.closest('tr');
    tr.querySelector('.l1').value = e.linha1;
    tr.querySelector('.l2').value = e.linha2;
    tr.querySelector('.l3').value = e.linha3;
    tr.querySelector('.ty').value = e.textoy || 0;
  }
  refresh();
}
async function loadNames() {
  try {
    // se já temos handle guardado, tentar reutilizá-lo (pede permissão com este clique)
    if (!namesHandle) namesHandle = await idbGet('nomesHandle').catch(() => null);
    if (namesHandle) {
      const p = await namesHandle.requestPermission({ mode: 'readwrite' });
      if (p === 'granted') {
        applyNames(parseNames(await (await namesHandle.getFile()).text()), 'nomes.txt');
        return;
      }
    }
    let text;
    if (window.showOpenFilePicker) {
      const [h] = await window.showOpenFilePicker({
        types: [{ description: 'nomes.txt', accept: { 'text/plain': ['.txt'] } }]
      });
      namesHandle = h;
      await idbSet('nomesHandle', h).catch(() => {});
      text = await (await h.getFile()).text();
    } else {
      text = await new Promise((res) => {
        const inp = document.createElement('input');
        inp.type = 'file'; inp.accept = '.txt';
        inp.onchange = () => { const r = new FileReader(); r.onload = () => res(r.result); r.readAsText(inp.files[0], 'utf-8'); };
        inp.click();
      });
    }
    applyNames(parseNames(text), 'nomes.txt');
  } catch (e) { /* cancelado */ }
}
async function saveNames() {
  // junta os lotes atuais à lista e grava no nomes.txt
  for (const tr of document.querySelectorAll('#batches tbody tr')) {
    const l1 = tr.querySelector('.l1').value.trim();
    if (!l1) continue;
    const entry = {
      name: l1, linha1: l1,
      linha2: tr.querySelector('.l2').value.trim(),
      linha3: tr.querySelector('.l3').value.trim(),
      textoy: num(tr.querySelector('.ty').value)
    };
    const i = NAMES.findIndex(x => x.linha1 === l1);
    if (i >= 0) NAMES[i] = entry; else NAMES.push(entry);
  }
  const text = serializeNames(NAMES);
  applyNames(NAMES, 'guardado');
  // no site: gravar no servidor (endpoint privado com sessão admin)
  if (location.protocol !== 'file:') {
    try {
      const r = await fetch('nomes.php', {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain; charset=utf-8' },
        body: text
      });
      if (r.ok) {
        document.getElementById('namesInfo').textContent = `${NAMES.length} nome(s) · gravado no servidor ✓`;
        return;
      }
    } catch (e) {}
  }
  try {
    if (!namesHandle) namesHandle = await idbGet('nomesHandle').catch(() => null);
    if (namesHandle && (await namesHandle.requestPermission({ mode: 'readwrite' })) === 'granted') {
      const w = await namesHandle.createWritable();
      await w.write(text); await w.close();
      document.getElementById('namesInfo').textContent = `${NAMES.length} nome(s) · gravado em nomes.txt ✓`;
      return;
    }
  } catch (e) {}
  // sem handle: descarregar um nomes.txt novo para substituir na pasta
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([text], { type: 'text/plain' }));
  a.download = 'nomes.txt';
  a.click();
  document.getElementById('namesInfo').textContent = `${NAMES.length} nome(s) · transferido nomes.txt (substitua o da pasta)`;
}
/* arrastar e largar também funciona */
document.addEventListener('dragover', e => e.preventDefault());
document.addEventListener('drop', e => {
  e.preventDefault();
  const f = [...e.dataTransfer.files].find(f => f.name.endsWith('.txt'));
  if (f) { const r = new FileReader(); r.onload = () => applyNames(parseNames(r.result), f.name); r.readAsText(f, 'utf-8'); }
});
/* ---------- arranque: autoload ---------- */
(async function initNames() {
  let loadedFromMemory = false;
  // 1) memória local (instantâneo)
  try {
    const c = localStorage.getItem('miaNames');
    if (c) { applyNames(JSON.parse(c), 'memória'); loadedFromMemory = true; }
  } catch (e) {}
  // 2) no site: endpoint privado nomes.php (sessão admin; ficheiro fora da pasta pública)
  if (location.protocol !== 'file:') {
    try {
      const r = await fetch(`nomes.php?t=${Date.now()}`, { cache: 'no-store' });
      if (r.ok) {
        const entries = parseNames(await r.text());
        if (entries.length) { applyNames(entries, 'servidor (auto)'); return; }
      }
    } catch (e) {}
  }
  // 3) tentar ler nomes.txt da mesma pasta diretamente
  try {
    const namesUrl = location.protocol === 'file:' ? 'nomes.txt' : `nomes.txt?t=${Date.now()}`;
    const r = await fetch(namesUrl, { cache: 'no-store' });
    if (r.ok) { applyNames(parseNames(await r.text()), 'nomes.txt (auto)'); return; }
  } catch (e) {}
  // 3) handle guardado de uma sessão anterior (silencioso se a permissão persistir)
  try {
    namesHandle = await idbGet('nomesHandle');
    if (namesHandle && (await namesHandle.queryPermission({ mode: 'readwrite' })) === 'granted') {
      applyNames(parseNames(await (await namesHandle.getFile()).text()), 'nomes.txt (auto)');
      return;
    }
    if (namesHandle && NAMES.length) {
      document.getElementById('namesInfo').textContent += ' · clique no botão da pasta para reler o ficheiro';
    }
  } catch (e) {}
  if (loadedFromMemory) {
    document.getElementById('namesInfo').textContent += ' · ficheiro não relido; clique em Carregar nomes.txt';
  }
})();

/* ---------- geração ---------- */
function download(name, blob) {
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[ch]));
}
async function tryGenerate() {
  try {
    await generate();
  } catch (e) {
    console.error(e);
    const msg = e && (e.message || e.name) ? `${e.name || 'Erro'}: ${e.message || ''}` : e;
    document.getElementById('result').innerHTML =
      `<p style="color:#c0392b;font-weight:600">Erro ao gerar: ${escapeHtml(msg)}</p>`;
  }
}

async function generate() {
  const batches = readBatches();
  if (!batches.length) { alert('Adicione pelo menos um lote.'); return; }
  const contorno = getCutOutline();
  const soLinhas = document.getElementById('cutlineOnly').checked;
  // Sem linha à volta não há guia para cortar — e só se dá por isso depois de
  // imprimir. Avisa antes de gastar folha.
  if (!contorno.on && !soLinhas &&
      !confirm('A linha à volta do cartão está desligada: o PDF sai sem guia para cortar.\n\nGerar na mesma?')) {
    document.getElementById('result').innerHTML = '<p class="muted">Cancelado. Ligue “Linha à volta do cartão” no painel das definições.</p>';
    return;
  }
  const margin = num(document.getElementById('margin').value);
  const off = getOffsets();
  const landscape = isLandscapeLayout();
  const draft = document.getElementById('draft').checked;
  const genSvg = document.getElementById('gensvg').checked;
  const offTag = (off.gx || off.gy || off.sx || off.sy)
    ? `_G${off.gx},${off.gy}_F${off.sx},${off.sy}` : '';
  const res = document.getElementById('result');
  res.innerHTML = '<p>A gerar…</p>';
  await new Promise(r => setTimeout(r, 30));

  if (off.ptc) { await generatePTC(batches, off, res); return; }

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4', compress: true });
  const svgFiles = new Map();
  const pageList = [];
  let pageNo = 0, first = true;

  const sizeOrder = [];
  for (const b of batches) if (!sizeOrder.includes(b.tpl.size)) sizeOrder.push(b.tpl.size);

  for (const sizeKey of sizeOrder) {
    const group = batches.filter(b => b.tpl.size === sizeKey);
    const s = SIZES[sizeKey];
    const seq = [];
    for (const b of group) {
      const bi = batches.indexOf(b);
      // No modo "só as linhas" não se compõe o cartão: a folha já está impressa.
      const png = soLinhas ? null
        : (await composePlacedCard(b.tpl, b.lines, b.ty, landscape, b.nums)).toDataURL('image/png');
      for (let k = 0; k < b.qty; k++) seq.push({ png, alias: 'lote' + bi, lote: bi + 1 });
    }
    const sheets = layoutSheets(sizeKey, seq.length, margin, landscape);
    let idx = 0;
    for (const sheet of sheets) {
      if (!first) doc.addPage(); first = false; pageNo++;
      const counts = new Map();
      for (const c of sheet.cards) {
        const card = seq[idx++];
        const d = cardDims(sizeKey, c);
        if (soLinhas) {
          // Só o rectângulo, nas mesmas posições, para imprimir por cima de uma
          // folha já feita. Vectorial, para o traço sair exacto.
          const lw = Math.max(0.02, contorno.mm || 0.1);
          const cor = hexParaRgb(contorno.cor);
          doc.setDrawColor(cor[0], cor[1], cor[2]);
          doc.setLineWidth(lw);
          doc.rect(c.x + lw / 2, c.y + lw / 2, d.w - lw, d.h - lw);
        } else {
          doc.addImage(card.png, 'PNG', c.x, c.y, d.w, d.h, card.alias);
        }
        counts.set(card.lote, (counts.get(card.lote) || 0) + 1);
      }
      if (draft && !s.noCut) {
        // imprime as linhas de corte (com offsets) por cima — para calibração
        const g = sheetCutGeometry(sizeKey, sheet, off);
        doc.setDrawColor(232, 67, 147);
        doc.setLineWidth(0.15);
        for (const [x1, y1, x2, y2] of g.segs) doc.line(x1, y1, x2, y2);
        for (const pts of g.slits)
          for (let i = 1; i < pts.length; i++) doc.line(pts[i-1][0], pts[i-1][1], pts[i][0], pts[i][1]);
        doc.setFontSize(8); doc.setTextColor(232, 67, 147);
        doc.text('RASCUNHO — linhas de corte impressas para calibração', 105, 4, { align: 'center' });
      }
      const sizePt = sizeLabel(sizeKey);
      const orientTag = landscape ? '_deitado' : '';
      // Ímanes não levam corte: não há SVG nem linhas a acompanhar a página.
      const svgName = s.noCut
        ? 'sem corte'
        : `${off.grid ? 'recorte' : 'fendas'}_${sizePt}${orientTag}_${sheet.n}cartoes${sheet.posTag || ''}_m${margin}${offTag}.svg`;
      if (!s.noCut && !svgFiles.has(svgName)) svgFiles.set(svgName, sheetCutSVG(sizeKey, sheet, off));
      const lotesTxt = [...counts.entries()].map(([l, n]) => `lote ${l} ×${n}`).join(' + ');
      pageList.push({ pageNo, batch: lotesTxt, tpl: sizePt + (landscape ? ' deitado' : ''), n: sheet.n, svg: svgName });
      if (!soLinhas) {   // numa folha já impressa o rodapé só sujava
        doc.setFontSize(7); doc.setTextColor(160);
        doc.text(`pág. ${pageNo} · ${lotesTxt} · SVG: ${svgName}`, 105, 296, { align: 'center' });
      }
    }
  }

  const stamp = new Date().toISOString().slice(0, 16).replace(/[-T:]/g, '').slice(0, 12);
  const pdfName = `${soLinhas ? 'so_linhas_' : 'imprimir_'}${draft ? 'RASCUNHO_' : ''}${stamp}.pdf`;
  download(pdfName, doc.output('blob'));
  if (genSvg) {
    let delay = 400;
    for (const [name, content] of svgFiles) {
      setTimeout(() => download(name, new Blob([content], { type: 'image/svg+xml' })), delay);
      delay += 400;
    }
  }

  res.innerHTML = `<p class="ok">✓ Gerado: ${pdfName}${genSvg ? ' + ' + svgFiles.size + ' SVG(s)' : ' (SVGs não gerados — use os já transferidos indicados na tabela)'}</p>
    <table><tr><th>Página</th><th>Lotes</th><th>Tamanho</th><th>Cartões</th><th>SVG de corte</th></tr>
    ${pageList.map(p => `<tr><td>${p.pageNo}</td><td>${p.batch}</td><td>${p.tpl}</td><td>${p.n}</td><td>${p.svg}</td></tr>`).join('')}
    </table>
    <p class="muted">Se o browser pedir permissão para “transferir vários ficheiros”, aceite.</p>
    ${soLinhas ? '<p class="muted"><b>Só as linhas:</b> volte a pôr a folha já impressa na impressora, na mesma orientação, e imprima este PDF a 100% (sem “ajustar à página”).</p>' : ''}`;
}


/* ---------- geração Print Then Cut ---------- */
async function generatePTC(batches, off, res) {
  const files = [];
  const pageList = [];
  let pageNo = 0;
  const sizeOrder = [];
  for (const b of batches) if (!sizeOrder.includes(b.tpl.size)) sizeOrder.push(b.tpl.size);
  // Print Then Cut existe para o Cricut cortar — os ímanes não levam corte.
  const semCorte = sizeOrder.filter(k => SIZES[k].noCut).map(k => sizeLabel(k));
  if (semCorte.length) {
    res.innerHTML = `<p style="color:#c0392b;font-weight:600">O Print Then Cut não se aplica a ${escapeHtml(semCorte.join(', '))} — estes cartões não levam corte. Desligue o Print Then Cut e gere só o PDF.</p>`;
    return;
  }
  for (const sizeKey of sizeOrder) {
    const group = batches.filter(b => b.tpl.size === sizeKey);
    const s = SIZES[sizeKey];
    const seq = [];
    for (const b of group) {
      const cv = await composeCard(b.tpl, b.lines, null, b.ty, b.nums);
      for (let k = 0; k < b.qty; k++) seq.push({ cv, lote: batches.indexOf(b) + 1 });
    }
    const sheets = ptcLayoutSheets(sizeKey, seq.length);
    const pxmm = 639 / s.w;
    let idx = 0;
    for (const sheet of sheets) {
      pageNo++;
      const bc = document.createElement('canvas');
      bc.width = Math.round(sheet.blockW * pxmm);
      bc.height = Math.round(sheet.blockH * pxmm);
      const ctx = bc.getContext('2d');
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, bc.width, bc.height);
      const counts = new Map();
      for (const c of sheet.cards) {
        const card = seq[idx++];
        ctx.drawImage(card.cv, Math.round(c.x * pxmm), Math.round(c.y * pxmm),
                      Math.round(s.w * pxmm), Math.round(s.h * pxmm));
        counts.set(card.lote, (counts.get(card.lote) || 0) + 1);
      }
      const svg = ptcSVG(sizeKey, sheet, off, bc.toDataURL('image/png'));
      const sizePt = sizeKey === 'big' ? 'grande' : 'pequeno';
      const name = `ptc_${sizePt}_pag${pageNo}_${sheet.n}cartoes.svg`;
      files.push([name, svg]);
      const lotesTxt = [...counts.entries()].map(([l, n]) => `lote ${l} ×${n}`).join(' + ');
      pageList.push({ pageNo, batch: lotesTxt, tpl: sizePt, n: sheet.n,
                      dim: `${sheet.blockW.toFixed(1)} × ${sheet.blockH.toFixed(1)} mm`, name });
    }
  }
  let delay = 100;
  for (const [name, content] of files) {
    setTimeout(() => download(name, new Blob([content], { type: 'image/svg+xml' })), delay);
    delay += 500;
  }
  res.innerHTML = `<p class="ok">✓ Print Then Cut: ${files.length} SVG(s) — sem PDF (a impressão é feita pelo Design Space)</p>
    <table><tr><th>Pág.</th><th>Lotes</th><th>Tamanho</th><th>Cartões</th><th>Ficheiro · dimensões reais</th></tr>
    ${pageList.map(p => `<tr><td>${p.pageNo}</td><td>${p.batch}</td><td>${p.tpl}</td><td>${p.n}</td><td>${p.name} · ${p.dim}</td></tr>`).join('')}
    </table>
    <p class="muted">No Design Space: Upload do SVG → confirmar a <b>largura exata</b> indicada acima → selecionar tudo → <b>Attach/Anexar</b> → a imagem fica Print Then Cut e as linhas ficam Basic Cut → imprimir do Design Space na ET‑8550 (escala 100%) → cortar.</p>`;
}

/* ---------- pré-preenchimento por URL ----------
   Permite chegar com tudo escolhido a partir de um link, sem passar pela
   tabela. Nunca gera sozinho: o PDF continua a sair só do botão, para haver
   sempre uma pré-visualização antes de gastar folha.

   Lotes (repetível), campos separados por "|" e omissíveis pelo fim:
     ?lote=modelo|linha1|linha2|linha3|qtd|turma|ano|textoY
   Atalho de três campos:
     ?lote=modelo|linha1|qtd
   Um lote só, em parâmetros soltos:
     ?cartao=modelo&linha1=…&linha2=…&linha3=…&qtd=20&turma=…&ano=…&textoy=…

   Definições: margem, deitado, contorno, contornoMm, contornoCor,
   contornoSuave, solinhas, ptc, gensvg, legado, rascunho, gx, gy, sx, sy. */
function parseLote(valor) {
  const p = String(valor).split('|').map(s => s.trim());
  const tpl = p[0];
  if (!TEMPLATES.some(t => t.id === tpl)) return null;
  // Atalho: modelo|nome|qtd. Distingue-se do formato longo porque o terceiro
  // campo é um número — na forma longa esse lugar é a linha 3.
  if (p.length === 3 && /^\d+$/.test(p[2])) {
    return { tpl, l1: p[1], qty: parseInt(p[2], 10) };
  }
  return {
    tpl,
    l1: p[1] || '', l2: p[2] || '', l3: p[3] || '',
    qty: parseInt(p[4], 10) || 12,
    turma: p[5] || '', ano: p[6] || '', ty: num(p[7])
  };
}

function applyUrlParams() {
  const q = new URLSearchParams(location.search);
  const lotes = [];

  for (const v of q.getAll('lote')) {
    const lote = parseLote(v);
    if (lote) lotes.push(lote);
  }

  const cartao = q.get('cartao');
  if (cartao && TEMPLATES.some(t => t.id === cartao)) {
    lotes.push({
      tpl: cartao,
      l1: q.get('linha1') || '', l2: q.get('linha2') || '', l3: q.get('linha3') || '',
      qty: parseInt(q.get('qtd'), 10) || 12,
      turma: q.get('turma') || '', ano: q.get('ano') || '', ty: num(q.get('textoy'))
    });
  }

  const set = (nome, id) => { if (q.has(nome)) document.getElementById(id).value = q.get(nome); };
  const marcar = (nome, id) => {
    if (!q.has(nome)) return;
    const v = q.get(nome);
    document.getElementById(id).checked = !(v === '0' || v === 'false' || v === 'nao' || v === 'não');
  };

  set('margem', 'margin');
  set('contornoMm', 'cutlineW');
  set('contornoCor', 'cutlineC');
  set('gx', 'offGx'); set('gy', 'offGy'); set('sx', 'offSx'); set('sy', 'offSy');
  marcar('deitado', 'landscape');
  marcar('contorno', 'cutline');
  marcar('contornoSuave', 'cutlineA');
  marcar('solinhas', 'cutlineOnly');
  marcar('ptc', 'ptc');
  marcar('gensvg', 'gensvg');
  marcar('legado', 'legacy');
  marcar('rascunho', 'draft');

  if (!lotes.length) { addBatch(); return; }
  lotes.forEach(addBatch);
  document.querySelector('.gen').classList.add('pronto');
}

applyUrlParams();

/* ---------- link partilhável (o inverso do pré-preenchimento) ---------- */
const LAN_ORIGIN = <?= json_encode($miaLanOrigin) ?>;

function construirLink() {
  const q = new URLSearchParams();

  for (const tr of document.querySelectorAll('#batches tbody tr')) {
    const v = c => tr.querySelector('.' + c).value.trim();
    const qty = parseInt(v('qty'), 10) || 0;
    if (!qty) continue;
    // Campos vazios do fim não vão para o link, para ficar legível no WhatsApp.
    const campos = [v('tpl'), v('l1'), v('l2'), v('l3'), String(qty), v('turma'), v('ano'), v('ty') === '0' ? '' : v('ty')];
    while (campos.length && campos[campos.length - 1] === '') campos.pop();
    q.append('lote', campos.join('|'));
  }
  if (![...q.keys()].length) return null;

  // Só o que estiver fora do valor por omissão: um link curto é um link que se
  // consegue ler antes de clicar.
  const el = id => document.getElementById(id);
  const seDif = (nome, id, omissao) => { if (el(id).value !== omissao) q.set(nome, el(id).value); };
  const seLigado = (nome, id) => { if (el(id).checked) q.set(nome, '1'); };
  const seDesligado = (nome, id) => { if (!el(id).checked) q.set(nome, '0'); };

  seDif('margem', 'margin', '3');
  seDif('contornoMm', 'cutlineW', '0.1');
  seDif('contornoCor', 'cutlineC', '#dcdcdc');
  for (const [nome, id] of [['gx', 'offGx'], ['gy', 'offGy'], ['sx', 'offSx'], ['sy', 'offSy']]) seDif(nome, id, '0');
  seLigado('deitado', 'landscape');
  seLigado('solinhas', 'cutlineOnly');
  seLigado('ptc', 'ptc');
  seLigado('gensvg', 'gensvg');
  seLigado('legado', 'legacy');
  seLigado('rascunho', 'draft');
  seDesligado('contorno', 'cutline');
  seDesligado('contornoSuave', 'cutlineA');

  const origem = LAN_ORIGIN || location.origin;
  return origem + location.pathname + '?' + q.toString();
}

async function copiarLink(btn) {
  const url = construirLink();
  if (!url) { alert('Adicione pelo menos um lote com quantidade.'); return; }
  const original = btn.innerHTML;
  try {
    await navigator.clipboard.writeText(url);
  } catch (e) {
    // Sem permissão de área de transferência (ou fora de HTTPS): mostra o link
    // já selecionado para copiar à mão.
    prompt('Copie o link:', url);
    return;
  }
  btn.innerHTML = '&#10003; Copiado';
  btn.disabled = true;
  setTimeout(() => { btn.innerHTML = original; btn.disabled = false; }, 1800);
}

</script>
</body>
</html>